begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,review_id uuid,draft_id uuid,generation_id uuid,claim uuid,receipt jsonb,model_input jsonb,policy jsonb);
insert into fixture values(gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,null,'{"origin":"console","policyVersion":"reviewflow-policy-v1","policy":{"policyClass":"standard","requiresHumanReview":false},"textPolicy":{"passed":true,"violations":[]}}');
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222','ReviewFlow responses rollback fixture' from fixture;
insert into public.reviews(id,property_id,platform,review_text,reviewer_name,rating,response_status) select review_id,property_id,'other','The pool was clean.','Fixture reviewer',5,'pending' from fixture;
create function pg_temp.draft_input(extra jsonb default '{}') returns jsonb language plpgsql as $$declare f fixture;s jsonb;begin select * into f from fixture;s:=public.reviewflow_response_context(f.property_id,f.actor_id,f.review_id);return jsonb_build_object('reviewId',f.review_id,'sourceVersion',s->'context'->'review'->'sourceVersion','contextHash',s->>'contextHash','responseSetHash',s->>'responseSetHash','replacePending',true,'tone','professional','reason','Reviewed the current review and property facts','responseText','Thank you for sharing your experience of the pool with our team.')||extra;end$$;
create function pg_temp.save_draft(id uuid default null,extra jsonb default '{}') returns jsonb language plpgsql as $$declare f fixture;begin select * into f from fixture;return public.commit_reviewflow_response_draft(coalesce(save_draft.id,f.draft_id),f.property_id,f.actor_id,pg_temp.draft_input(extra),f.policy);end$$;
create function pg_temp.decision(action text,id uuid default null,extra jsonb default '{}') returns jsonb language plpgsql as $$declare f fixture;d public.review_responses;begin select * into f from fixture;select * into d from public.review_responses where review_responses.id=coalesce(decision.id,f.draft_id);return jsonb_build_object('responseId',d.id,'expectedVersion',d.version,'sourceVersion',d.source_version,'contextHash',d.context_hash,'contentHash',d.content_hash,'action',action,'reason','Reviewed exact public response text')||extra;end$$;
do $$declare f fixture;r jsonb;payload jsonb;begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.reviewflow_response_context(uuid,uuid,uuid)','execute') and not has_table_privilege('authenticated','public.review_responses','update'),'browser cannot read private context or bypass recorded draft mutations');
 perform pg_temp.check(public.reviewflow_response_context(f.property_id,gen_random_uuid(),f.review_id)->>'state'='forbidden','unknown actor cannot load saved response context');
 perform pg_temp.check(pg_temp.save_draft(null,'{"sourceVersion":99}')->>'state'='stale_context','new draft must match current source revision');
 payload:=pg_temp.draft_input();r:=public.commit_reviewflow_response_draft(f.draft_id,f.property_id,f.actor_id,payload,f.policy);
 perform pg_temp.check(r->>'state'='saved','draft, review state and proposal save atomically');
 perform pg_temp.check(public.commit_reviewflow_response_draft(f.draft_id,f.property_id,f.actor_id,payload,f.policy)->>'state'='replayed','lost draft save response returns exact saved decision');
 perform pg_temp.check((select status='draft' and source_version=1 and context_snapshot_id is not null and content_hash is not null from public.review_responses where id=f.draft_id),'draft records exact source, context and text identity');
 perform pg_temp.check((select a.proposal_decision_status='proposed' and a.execution_status='pending_approval' from public.review_responses d join public.shared_action_attempts a on a.id=d.shared_action_attempt_id where d.id=f.draft_id),'saved text creates a proposal without a publication approval');
 perform pg_temp.check((select status='awaiting_approval' from public.reputation_cases where review_id=f.review_id),'case reflects the saved draft without claiming resolution');
 perform pg_temp.check(pg_temp.save_draft(gen_random_uuid(),'{"replacePending":false}')->>'state'='replacement_review_required','new draft cannot silently replace pending approval');
 begin update public.review_responses set response_text='Changed approved words' where id=f.draft_id;raise exception 'FAIL editable text';exception when raise_exception then if SQLERRM<>'Save response edits as a new draft version' then raise;end if;end;
 perform pg_temp.check(true,'saved draft text is immutable');
end$$;
do $$declare f fixture;r jsonb;command_id uuid:=gen_random_uuid();payload jsonb;original uuid;begin select * into f from fixture;payload:=pg_temp.decision('approve');
 update public.profiles set role='member' where id=f.actor_id;
 perform pg_temp.check(public.decide_reviewflow_response(command_id,f.property_id,f.actor_id,payload,f.policy)->>'state'='manager_required','member cannot grant manager approval');
 update public.profiles set role='admin' where id=f.actor_id;
 perform pg_temp.check(public.decide_reviewflow_response(command_id,f.property_id,f.actor_id,payload,f.policy)->>'state'='saved','manager approves exact saved content');
 perform pg_temp.check(public.decide_reviewflow_response(command_id,f.property_id,f.actor_id,payload,'{}')->>'state'='replayed','lost approval reply recovers its stored decision');
 perform pg_temp.check((select status='approved' and version=2 and posted_at is null from public.review_responses where id=f.draft_id),'approval does not claim publication');
 perform pg_temp.check((select count(*)=1 from public.shared_approvals where action_attempt_id=(select shared_action_attempt_id from public.review_responses where id=f.draft_id)),'approval is reflected once in shared governance');
 perform pg_temp.check(public.decide_reviewflow_response(gen_random_uuid(),f.property_id,f.actor_id,payload,f.policy)->>'state'='stale_response','old response versions cannot be approved twice');
 original:=f.draft_id;update fixture set draft_id=gen_random_uuid();r:=pg_temp.save_draft();
 perform pg_temp.check(r->>'state'='saved' and(select superseded_at is not null and status='approved' from public.review_responses where id=original),'editing preserves the prior approved text and marks it superseded');
 perform pg_temp.check((select a.execution_status='cancelled' from public.review_responses d join public.shared_action_attempts a on a.id=d.shared_action_attempt_id where d.id=original),'replacing approved text cancels its old execution permission');
end$$;
do $$declare f fixture;r jsonb;payload jsonb;begin select * into f from fixture;payload:=pg_temp.decision('approve');
 update public.properties set brand_voice='New reviewed brand voice' where id=f.property_id;
 perform pg_temp.check(public.decide_reviewflow_response(gen_random_uuid(),f.property_id,f.actor_id,payload,f.policy)->>'state'='stale_context','changed property facts prevent stale draft approval');
 perform pg_temp.check(public.decide_reviewflow_response(gen_random_uuid(),f.property_id,f.actor_id,pg_temp.decision('reject'),f.policy)->>'state'='saved','reviewer can still reject stale text');
 perform pg_temp.check((select response_status='pending' from public.reviews where id=f.review_id),'rejection returns review to pending instead of marking it posted');
end$$;
create function pg_temp.start_generation(id uuid default null) returns jsonb language plpgsql as $$declare f fixture;s jsonb;input jsonb;model jsonb;r jsonb;begin select * into f from fixture;s:=public.reviewflow_response_context(f.property_id,f.actor_id,f.review_id);input:=pg_temp.draft_input()-'responseText';model:=jsonb_build_object('context',s->'context','source',jsonb_build_object('reviewText',s->'context'->'review'->>'reviewText','tone','professional','grounding',jsonb_build_object('citedFacts','[]'::jsonb)),'model','fixture-model','systemPrompt','Fixture public response prompt','userPrompt','The pool was clean.','promptVersion','response-v3','taxonomyVersion','multifamily-v1','policyVersion','reviewflow-policy-v1');r:=public.begin_reviewflow_response_generation(coalesce(start_generation.id,f.generation_id),f.property_id,f.actor_id,input,model);update fixture set model_input=model;return r;end$$;
update fixture set receipt=jsonb_build_object('status','received','providerId','fixture-result','content',jsonb_build_object('responseText','Thank you for sharing your experience of the pool with our team.','usedFacts','[]'::jsonb,'refusalReason',null)::text);
create function pg_temp.apply_generation(id uuid default null) returns jsonb language plpgsql as $$declare f fixture;run public.reviewflow_response_generation_requests;generated jsonb;begin select * into f from fixture;select * into run from public.reviewflow_response_generation_requests where reviewflow_response_generation_requests.id=coalesce(apply_generation.id,f.generation_id);generated:=(run.raw_result->>'content')::jsonb-'refusalReason';generated:=generated||jsonb_build_object('provenance',jsonb_build_object('model','fixture-model','promptVersion','response-v3','taxonomyVersion','multifamily-v1'),'usage',jsonb_build_object('model','fixture-model'),'policyCheck',jsonb_build_object('passed',true));return public.apply_reviewflow_response_generation(run.id,f.property_id,f.actor_id,jsonb_build_object('resultHash',run.result_hash,'response',generated,'policy',f.policy));end$$;
do $$declare f fixture;r jsonb;begin select * into f from fixture;
 perform pg_temp.check(pg_temp.start_generation()->>'state'='queued','generation saves frozen context before any model intent');
 perform pg_temp.check(pg_temp.start_generation()->>'state'='queued' and pg_temp.start_generation(gen_random_uuid())->>'state'='busy','request replay and competing generation cannot duplicate active work');
 r:=public.claim_reviewflow_response_generation(f.generation_id);update fixture set claim=(r->>'claimToken')::uuid;
 perform pg_temp.check(r->>'state'='invoke_once' and public.claim_reviewflow_response_generation(f.generation_id)->>'state'='running','one saved model intent survives a lost claim reply');
 perform pg_temp.check(public.record_reviewflow_response_generation_result(f.generation_id,(r->>'claimToken')::uuid,f.receipt)->>'requestState'='result_ready','raw response result saves before any new draft');
 perform pg_temp.check((select count(*)=2 from public.review_responses where review_id=f.review_id),'receiving raw output alone cannot replace response text');
end$$;
create function pg_temp.fail_response_history() returns trigger language plpgsql as $$begin if new.action='review.response.generation_completed' and new.phase='succeeded' then raise exception 'Fixture response history failure';end if;return new;end$$;
create trigger response_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_response_history();
do $$declare f fixture;begin select * into f from fixture;
 begin perform pg_temp.apply_generation();raise exception 'FAIL missing atomic history';exception when raise_exception then if SQLERRM<>'Fixture response history failure' then raise;end if;end;
 perform pg_temp.check((select state='result_ready' and raw_result is not null from public.reviewflow_response_generation_requests where id=f.generation_id) and(select count(*)=2 from public.review_responses where review_id=f.review_id),'failed completion rolls back draft and governance but retains raw model result');
end$$;
drop trigger response_fixture_failure on public.shared_action_events;
do $$declare f fixture;r jsonb;draft uuid;begin select * into f from fixture;
 r:=pg_temp.apply_generation();draft:=(r->>'responseId')::uuid;
 perform pg_temp.check(r->>'state'='saved' and pg_temp.apply_generation()->>'state'='replayed','stored response recovery creates one draft without another model call');
 perform pg_temp.check((select state='completed' and response_id=draft from public.reviewflow_response_generation_requests where id=f.generation_id),'generation links its saved draft after atomic completion');
 perform pg_temp.check((select status='draft' and response_type='ai_generated' and approved_at is null and posted_at is null from public.review_responses where id=draft),'recovered model text still requires manager approval');
 perform pg_temp.check((select ep.origin='workflow' from public.shared_action_events ev join public.shared_action_episodes ep on ep.id=ev.episode_id where ev.action='review.response.draft_saved' and ev.result->>'responseId'=draft::text),'generated draft does not masquerade as a human-authored action');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where property_id=f.property_id and row_to_json(shared_action_events)::text like '%Thank you for sharing%'),'raw response text remains outside the general activity stream');
end$$;
do $$declare f fixture;r jsonb;run_id uuid:=gen_random_uuid();token uuid;begin select * into f from fixture;perform pg_temp.start_generation(run_id);r:=public.claim_reviewflow_response_generation(run_id);token:=(r->>'claimToken')::uuid;
 perform pg_temp.check(public.control_reviewflow_response_generation(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('generationRequestId',run_id,'expectedVersion',2,'reason','Stop simulated generation'))->>'state'='saved','operator can stop started generation with its current version');
 perform pg_temp.check(public.record_reviewflow_response_generation_result(run_id,token,f.receipt)->>'requestState'='stopped' and pg_temp.apply_generation(run_id)->>'state'='stopped','late stopped output is retained without replacing any draft');
 run_id:=gen_random_uuid();perform pg_temp.start_generation(run_id);r:=public.claim_reviewflow_response_generation(run_id);perform public.record_reviewflow_response_generation_result(run_id,(r->>'claimToken')::uuid,f.receipt);update public.reviews set review_text='The pool has closed.' where id=f.review_id;
 perform pg_temp.check(pg_temp.apply_generation(run_id)->>'state'='held','result from an earlier source cannot replace the current response');
end$$;
select count(*) as passed_assertions from checks;
rollback;
